head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > P > selectedIndex]<br/>컴포넌트가 렌더링되고 처음 선택될 Tab 페이지의 인덱스를 설정합니다.",
    "validation" : [
        "컴포넌트가 렌더링되고 처음 선택될 Tab 페이지의 인덱스를 설정합니다.",
        "Tab 페이지의 인덱스는 0 부터 시작하며 값을 설정하지 않으면 0 으로 적용됩니다.",
        "음수값이나 잘못된 인덱스값으로 설정하면 Tab 페이지가 선택되지 않아 빈화면이 표시됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        selectedIndex: con_selectedIndex.getText(),
    };

    let cList = $c.gcm.createCList(properties);          
    let eList = $c.gcm.createEList(["onchange"]);

    $c.gcm.createBasicTabControl(cList, eList)    

    if (con_selectedIndex.getText() == "-1" || con_selectedIndex.getText() == "100")
        scwin.btn_checkContentEmpty_onclick();

    scwin.btn_getSelectedTabIndex_onclick();
}



scwin.target1_onchange = function (tabId, index, userTabId) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");
}



scwin.btn_checkContentEmpty_onclick = function (e) {
    let content1 = document.querySelector('div[id*=target1_contents_content1_body]');
    let content2 = document.querySelector('div[id*=target1_contents_content2_body]');
    let content3 = document.querySelector('div[id*=target1_contents_content3_body]');

    if (content1 == null && content2 == null && content3 == null)
        wf_body_bottom.getObj("scwin").setReturnValue("Content is empty");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("Content is not empty");
}



scwin.btn_getSelectedTabIndex_onclick = function (e) {      
    let rtn = target1.getSelectedTabIndex();

    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedTabIndex : " + rtn);
}
